    price_surge = df['close'].pct_change(5) > 0.05
    vol_surge = df['volume'] > vol_ma * 2.0
    pump_entry = (price_surge & vol_surge).fillna(False)

    recent_high = df['close'].rolling(window=20).max()
    dump_exit = (df['close'] < recent_high * 0.95).fillna(False)

    signals = pd.Series(0, index=df.index)
    in_pos = False

    for i in range(len(df)):
        if in_pos:
            if dump_exit.iloc[i]:
                signals.iloc[i] = 0
                in_pos = False
            else:
                signals.iloc[i] = 1
        else:
            if pump_entry.iloc[i]:
                signals.iloc[i] = 1
                in_pos = True
            else:
                signals.iloc[i] = 0
    return signals
